files.convex/telemetry.ts:
import { internalAction } from "./_generated/server";

/** The protected thing: the one function that sends telemetry out. */
export const send = internalAction({ handler: async () => {} });

/** A namesake whose generated path is longer: never a reference to send. */
export const sendAll = internalAction({ handler: async () => {} });

files.convex/events.ts:
import { mutation } from "./_generated/server";
import { internal } from "./_generated/api";

/** The chokepoint: every event is recorded here, and only here sent on. */
export const record = mutation({
  handler: async (ctx: any) => {
    await ctx.scheduler.runAfter(0, internal.telemetry.send, {});
  },
});

files.convex/leak.ts:
import { action } from "./_generated/server";
import { internal as generated } from "./_generated/api";

// internal.telemetry.send in a comment is no reference.
const said = "internal.telemetry.send";

export const flush = action({
  handler: async (ctx: any) => {
    await ctx.runAction(generated.telemetry.sendAll, { said });
    await ctx.runAction(
      generated
        .telemetry
        .send,
      {},
    );
  },
});

files.convex/http.ts:
import { httpRouter } from "convex/server";
import { httpAction } from "./_generated/server";
import { webhook } from "./webhooks";

const http = httpRouter();
http.route({ path: "/webhook", method: "POST", handler: webhook });
http.route({
  path: "/health",
  method: "GET",
  handler: httpAction(async () => new Response("ok")),
});
export default http;

files.convex/crons.ts:
import { cronJobs } from "convex/server";
import { internal } from "./_generated/api";

const crons = cronJobs();
crons.daily("flush telemetry", { hourUTC: 3, minuteUTC: 0 }, internal.telemetry["send"]);
export default crons;

